import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"CSV Import","description":"Import data from a CSV file into a Grid.","frontmatter":{"title":"CSV Import","description":"Import data from a CSV file into a Grid."},"headers":[],"relativePath":"en/grids/csv-import.md","filePath":"en/grids/csv-import.md","lastUpdated":1787319236000}'),i={name:"en/grids/csv-import.md"};function s(n,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="csv-import" tabindex="-1">CSV Import <a class="header-anchor" href="#csv-import" aria-label="Permalink to &quot;CSV Import&quot;">​</a></h1><p>Using <strong>Import from CSV</strong>, you bring data from a spreadsheet file into an existing Grid.</p><h2 id="requirement-utf-8" tabindex="-1">Requirement: UTF-8 <a class="header-anchor" href="#requirement-utf-8" aria-label="Permalink to &quot;Requirement: UTF-8&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">The file must be UTF-8 encoded</p><blockquote><p><em>The CSV file must be created in UTF-8 format.</em></p></blockquote><p>This is the most common source of errors. Depending on version and region, Excel does <strong>not</strong> automatically save CSV files as UTF-8 — the result is broken accented characters (<code>Müller</code> becomes <code>MÃ¼ller</code>).</p><p><strong>How to be sure:</strong></p><ul><li><strong>Excel:</strong> <em>Save As</em> → file type <strong>CSV UTF-8 (Comma delimited)</strong></li><li><strong>LibreOffice Calc:</strong> <em>Save As</em> → CSV → in the dialog, <strong>Character set: Unicode (UTF-8)</strong></li><li><strong>Google Sheets:</strong> exporting as CSV is always UTF-8</li></ul></div><p>If the format doesn&#39;t match, ApptiveGrid reports <em>The file format is invalid.</em></p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Check before importing</p><ol><li><strong>Create target columns.</strong> The import writes into existing fields. Create any missing columns with the <a href="/en/referenz/spaltentypen">right type</a> beforehand.</li><li><strong>Check flows.</strong> If a flow with the <em>New entry</em> trigger is attached to this Grid, it starts <strong>for every imported row</strong>. With 500 rows, that&#39;s 500 emails going out. Turn the flow off beforehand, or import into an intermediate Grid.</li><li><strong>Mind the entry limit.</strong> The number of entries per Grid depends on your plan.</li><li><strong>Take a backup.</strong> Before importing into a populated Grid, do a <a href="/en/grids/csv-export">CSV export</a> first.</li></ol></div><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><p>The import walks you through four steps.</p><h3 id="_1-·-read-csv-file" tabindex="-1">1 · Read CSV file <a class="header-anchor" href="#_1-·-read-csv-file" aria-label="Permalink to &quot;1 · Read CSV file&quot;">​</a></h3><ul><li>Use <strong>Load file</strong> to choose the file.</li><li><strong>Header row?</strong> indicates whether the first row contains column names.</li><li><strong>Read CSV</strong> starts the analysis.</li></ul><p>Afterward, you map the columns to each other. The table has two columns:</p><table tabindex="0"><thead><tr><th>Heading</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Grid</strong></td><td>The target column in ApptiveGrid</td></tr><tr><td><strong>CSV</strong></td><td>The source column from the file</td></tr></tbody></table><p>Set columns you don&#39;t want to bring over to <strong>Ignore</strong>.</p><div class="tip custom-block"><p class="custom-block-title">A header row saves mapping work</p><p>With a header row, the mapping shows meaningful names instead of &quot;Column 1,&quot; &quot;Column 2.&quot; For more than five columns, that&#39;s a noticeable difference — and one less source of errors.</p></div><h3 id="_2-·-preview" tabindex="-1">2 · Preview <a class="header-anchor" href="#_2-·-preview" aria-label="Permalink to &quot;2 · Preview&quot;">​</a></h3><p>Shows how the data would arrive.</p><div class="tip custom-block"><p class="custom-block-title">Actually look here</p><p>The preview is your last chance before writing. Check in particular:</p><ul><li><strong>Accented characters</strong> — broken means wrong encoding, cancel the import</li><li><strong>Dates</strong> — do they arrive as a date or as text?</li><li><strong>Numbers</strong> — is the decimal separator interpreted correctly?</li><li><strong>Select fields</strong> — do the values match the existing options?</li></ul></div><p>Click <strong>Import data</strong> to start.</p><h3 id="_3-·-importing" tabindex="-1">3 · Importing <a class="header-anchor" href="#_3-·-importing" aria-label="Permalink to &quot;3 · Importing&quot;">​</a></h3><p>Progress is shown: <em>Importing {number} entries.</em></p><h3 id="_4-·-complete" tabindex="-1">4 · Complete <a class="header-anchor" href="#_4-·-complete" aria-label="Permalink to &quot;4 · Complete&quot;">​</a></h3><p>Completion message: <em>{Number} entries imported successfully.</em></p><div class="tip custom-block"><p class="custom-block-title">Cross-check the number</p><p>Compare the reported number with the row count of your file. If they differ, rows were skipped — usually due to values that didn&#39;t fit.</p></div><h2 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td><code>MÃ¼ller</code> instead of <code>Müller</code></td><td>File isn&#39;t UTF-8. Re-save it, repeat the import.</td></tr><tr><td><em>The file format is invalid.</em></td><td>Not a valid CSV. Check the delimiter and encoding.</td></tr><tr><td><em>Unrecognized date format: {date}</em></td><td>Date format isn&#39;t readable. <code>YYYY-MM-DD</code> is the most reliable.</td></tr><tr><td>Numbers arrive as text</td><td>Target column is of type <em>Text</em>. Change the type first.</td></tr><tr><td>Select fields stay empty</td><td>The CSV values don&#39;t match any option. Create the options first, or enable <em>Allow other options</em>.</td></tr><tr><td>Fewer entries than rows</td><td>Rows with values that didn&#39;t fit were skipped.</td></tr><tr><td>Sudden flood of flow runs</td><td>A flow with <em>New entry</em> is attached to the Grid.</td></tr></tbody></table><h2 id="a-test-run-pays-off" tabindex="-1">A test run pays off <a class="header-anchor" href="#a-test-run-pays-off" aria-label="Permalink to &quot;A test run pays off&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Start with ten rows</p><p>For larger datasets: copy the first ten rows into their own file and import that first. If the result looks right, import the rest — otherwise you&#39;ll be cleaning up ten rows instead of a thousand.</p><p>To clean up a botched import, <a href="/en/grids/eintraege-loeschen">bulk deletion</a> helps; find the most recently imported entries by sorting on <em>Created at</em>.</p></div><h2 id="what-the-import-can-t-do" tabindex="-1">What the import can&#39;t do <a class="header-anchor" href="#what-the-import-can-t-do" aria-label="Permalink to &quot;What the import can&#39;t do&quot;">​</a></h2><ul><li><strong>Update existing entries.</strong> The import always creates new entries. There&#39;s no matching via a key column.</li><li><strong>Create links.</strong> References to other Grids can&#39;t be imported directly.</li><li><strong>Bring in files.</strong> Attachments have to be uploaded separately.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/csv-export">CSV Export</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common error messages</a></li></ul>',32)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
